def once_min_dp(values, amount):
    infinity = float("inf")
    best = [infinity] * (amount + 1)
    best[0] = 0
    for coin in values:
        for value in range(amount, coin - 1, -1):
            if best[value - coin] != infinity:
                candidate = best[value - coin] + 1
                if candidate < best[value]:
                    best[value] = candidate
    return None if best[amount] == infinity else best[amount]

print(once_min_dp([2], 4))
print(once_min_dp([2, 2], 4))
print(once_min_dp([2, 3], 5))
print(once_min_dp([], 0))

def advance_once(previous, coin):
    following = previous.copy()
    for value in range(coin, len(previous)):
        if previous[value - coin] is not None:
            candidate = previous[value - coin] + 1
            if following[value] is None or candidate < following[value]:
                following[value] = candidate
    return following

print(advance_once([0, None, None, None, None], 2))
print(advance_once([0, None, 1, None, None], 2))
print(advance_once([0], 3))

